INSERT INTO maintenance_reminders (
    id, mold_id, plan_id, plan_name, reminder_type, interval_value,
    next_due_date, next_due_cycles, reminder_count, status, sent_at, operator_id, notes,
    created_at, updated_at
) VALUES (
    #{id}, #{moldId}, #{planId}, #{planName}, #{reminderType}, #{intervalValue},
    #{nextDueDate}, #{nextDueCycles}, #{reminderCount}, #{status}, #{sentAt}, #{operatorId}, #{notes},
    #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE maintenance_reminders
mold_id = #{moldId}, plan_id = #{planId}, plan_name = #{planName}, reminder_type = #{reminderType}, interval_value = #{intervalValue}, next_due_date = #{nextDueDate}, next_due_cycles = #{nextDueCycles}, reminder_count = #{reminderCount}, status = #{status}, sent_at = #{sentAt}, operator_id = #{operatorId}, notes = #{notes}, updated_at = #{updatedAt},
WHERE id = #{id}

mapper.select:
SELECT r.id, r.mold_id, r.plan_id, m.mold_code, m.name AS mold_name, r.plan_name, r.reminder_type, r.interval_value, r.next_due_date, r.next_due_cycles, r.reminder_count, r.status, CASE r.status WHEN 1 THEN '待处理' WHEN 2 THEN '已提醒' WHEN 3 THEN '已完成' WHEN 4 THEN '已忽略' ELSE '' END AS status_desc, r.sent_at, r.operator_id, u.real_name AS operator_name, r.notes, r.created_at, r.updated_at FROM maintenance_reminders r LEFT JOIN molds m ON r.mold_id = m.id LEFT JOIN users u ON r.operator_id = u.id
AND r.mold_id = #{moldId}
AND (m.mold_code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
AND r.status = #{status}
AND r.reminder_type = #{reminderType}
ORDER BY r.created_at DESC
